<?php $title = 'Staff catalog | Maa Sarada'; require __DIR__ . '/header.php'; ?>
<div class="page-intro"><div><span class="eyebrow">STAFF CATALOG</span><h1><?= $product ? $e($product['name']) : 'Catalog overview.' ?></h1><p>Signed in as <?= $e($actor['name']) ?>. This view is read-only.</p></div><a class="button secondary" href="<?= $u('admin/products') ?>">Catalog overview ↗</a></div>
<p class="notice">This catalog is read-only. Product editing, image uploads and stock/order changes are not available in this screen.</p>
<?php if ($product): ?><article class="panel"><h2><?= $e($product['name']) ?></h2><p>Status: <?= $e($product['status']) ?> · Revision <?= $e($product['revision']) ?></p><p><?= $e($product['description']) ?></p><div class="grid"><?php foreach ($product['variants'] as $variant): ?><article class="panel"><h3><?= $e($variant['sku']) ?></h3><p><?= $m($variant['unit_price_minor']) ?> / <?= $e($variant['sell_unit']) ?></p><p>Available <?= $q($variant['available_milli'] ?? 0) ?> <?= $e($variant['sell_unit']) ?> · <?= $variant['enabled'] ? 'Enabled' : 'Disabled' ?></p></article><?php endforeach; ?></div></article>
<?php else: ?><div class="grid"><?php foreach ($products['items'] as $entry): ?><article class="panel"><h2><a href="<?= $u('admin/product') ?>?id=<?= $e($entry['id']) ?>"><?= $e($entry['name']) ?></a></h2><p><?= $e($entry['status']) ?> · <?= $e($entry['category_name']) ?></p><p><?= $entry['min_price_minor'] !== null ? $m($entry['min_price_minor']) : 'No enabled variant' ?></p></article><?php endforeach; ?></div><?php if (!$products['items']): ?><div class="empty-state"><h2>No products on this page.</h2><p>Real catalog records must be created through the authorized catalog workflow.</p></div><?php endif; ?><nav class="pagination" aria-label="Staff catalog pages"><?php foreach (['Previous'=>$products['page']-1,'Next'=>$products['page']+1] as $label=>$number): ?><?php if ($number >= 1 && $number <= $products['pages']): ?><a class="button secondary" href="<?= $u('admin/products') ?>?page=<?= $number ?>"><?= $e($label) ?></a><?php endif; ?><?php endforeach; ?></nav><?php endif; ?>
<?php require __DIR__ . '/footer.php'; ?>
